local function GenerateCode()
	local Code = "";
	for i = 1,3 do
		if math.random(1,2) == 1 then
			Code = Code .. math.random(0,9);
		else
			Code = Code .. string.char(math.random(65,90));
		end;
	end
	Code = Code .. "-";
	for i = 1,3 do
		if math.random(1,2) == 1 then
			Code = Code .. math.random(0,9);
		else
			Code = Code .. string.char(math.random(65,90));
		end;
	end
	return Code;
end


function CreateCode(Rewards)	
	local Code;
	local CodeAvailable = false;
	repeat 
		Code = GenerateCode();

		Codes:UpdateAsync(Code, function(Value)

			if Value == nil then
				CodeAvailable = true;
				return {
					Redeemed = false;
					Rewards = Rewards;
					--[[Rewards = {
						{RewardID = RewardID;RewardType = RewardType;};
					};]]
				};
			else
				print("Duplicate code generated.");
				return Value;
			end;

		end)

		wait();
	until CodeAvailable;
	return Code;
end


